                            t.HasCheckConstraint("ck_sales_invoices_number", "char_length(number) <= 16 AND number_prefix ~ '^[A-Z0-9]{1,7}$' AND sequence_number > 0 AND number = number_prefix || '-' || CASE WHEN sequence_number < 1000000 THEN lpad(sequence_number::text, 6, '0') ELSE sequence_number::text END");

                            t.HasCheckConstraint("ck_sales_invoices_only_regular_collects_tax", "tax_mode = 'GST_REGULAR' OR (cgst_total = 0 AND sgst_total = 0 AND igst_total = 0 AND cess_total = 0)");

                            t.HasCheckConstraint("ck_sales_invoices_paid", "change_due >= 0 AND paid_total - change_due = grand_total");

                            t.HasCheckConstraint("ck_sales_invoices_tax_mode", "tax_mode IN ('GST_REGULAR', 'GST_COMPOSITION', 'NOT_GST_REGISTERED')");

                            t.HasCheckConstraint("ck_sales_invoices_total", "grand_total = taxable_total + cgst_total + sgst_total + igst_total + cess_total + round_off AND abs(round_off) <= 0.5 AND grand_total = round(grand_total)");
                        });
                });

